import{c as r,Z as o,Q as l,j as n,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"天净沙·秋","description":"","frontmatter":{"title":"天净沙·秋","author":"白朴","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/3.md","filePath":"books/shici/yuanqu/3.md"}'),u={name:"books/shici/yuanqu/3.md"};function h(c,a,d,p,q,_){const e=o("PoemAuthor"),i=o("PoemNav");return l(),n("div",null,[a[0]||(a[0]=s('<h1 id="天净沙·秋" tabindex="-1">天净沙·秋 <a class="header-anchor" href="#天净沙·秋" aria-label="Permalink to &quot;天净沙·秋&quot;">​</a></h1><p><strong>[元] <a href="/authors/baipu.html">白朴</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。 青山绿水，白草红叶黄花。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>天净沙：曲牌名</li><li>残霞：晚霞</li><li>轻烟：淡淡的炊烟或雾气</li><li>寒鸦：寒天的乌鸦</li><li>飞鸿：飞翔的大雁</li><li>影下：雁影掠过</li><li>白草：枯萎的草，呈白色</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>夕阳西下，天边残留着晚霞，孤零零的村落笼罩在淡淡的炊烟之中，老树上栖息着寒鸦。一只大雁飞过，留下一道孤影。 远处是青翠的山峦和碧绿的流水，近处是白色的枯草、红色的枫叶和黄色的菊花。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是白朴《天净沙》四季组曲中的秋景之作，与马致远《天净沙·秋思》齐名，但风格迥异。马曲悲凉凄苦，白曲则明朗清丽。</p><p>前三句&quot;孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下&quot;，选取秋日黄昏的典型景物，营造出一种宁静而略带萧瑟的氛围。&quot;孤&quot;&quot;残&quot;&quot;寒&quot;等字虽带秋意，却并不凄苦，&quot;一点飞鸿影下&quot;更添几分灵动。</p><p>后两句&quot;青山绿水，白草红叶黄花&quot;，笔锋一转，以五种鲜明的色彩描绘出秋日山林的绚烂景致。青、绿、白、红、黄，色彩斑斓，打破了传统秋景的单调萧瑟，展现出秋天特有的明丽与丰富。全曲由暗到明，由静到动，层次分明，意境优美，是一首别具一格的秋之赞歌。</p>',12)),t(e,{name:"白朴",years:"1226年－约1306年",desc:"字太素，号兰谷，元代著名戏曲作家、散曲家，元曲四大家之一。其散曲风格清丽婉约，多写隐逸生活。",link:"/authors/baipu"}),t(i)])}const f=r(u,[["render",h]]);export{b as __pageData,f as default};
